{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS public.tuco_kids_ga_order_by_source_consolidated ( shop_name VARCHAR(65535), channel VARCHAR(65535), final_source VARCHAR(65535), date DATE, sessionmedium VARCHAR(65535), sessionsource VARCHAR(65535), sessionsourcemedium VARCHAR(65535), transactionid VARCHAR(65535), grosspurchaserevenue NUMERIC(18,2) ); drop table if exists public.tuco_kids_sales_consolidated_intermediate; CREATE TABLE public.tuco_kids_sales_consolidated_intermediate AS SELECT CAST(b.customer_id AS VARCHAR(256)) AS customer_id, UPPER(b.SHOP_NAME) AS SHOP_NAME, UPPER(b.marketplace) AS marketplace, UPPER(COALESCE(GA4.CHANNEL, b.FINAL_UTM_CHANNEL)) AS CHANNEL, UPPER(COALESCE(GA4.final_source, b.FINAL_UTM_SOURCE)) AS SOURCE, b.ORDER_ID, b.order_name AS reference_code, b.tags, b.PHONE, b.NAME, b.EMAIL, COALESCE( CAST(b.shipping_status_update_date AS TIMESTAMP), CAST(c.shipping_last_update_date AS TIMESTAMP), CAST(d.shipping_last_update_date AS TIMESTAMP) ) AS SHIPPING_LAST_UPDATE_DATE, b.SKU, b.PRODUCT_ID, UPPER(COALESCE(c.productname, b.PRODUCT_NAME)) AS PRODUCT_NAME, b.CURRENCY, UPPER(b.SHIPPING_CITY) AS CITY, UPPER(b.SHIPPING_STATE) AS State, UPPER(b.ORDER_STATUS) AS ORDER_STATUS, CAST(b.ORDER_TIMESTAMP AS DATE) AS Order_Date, CAST(b.ORDER_TIMESTAMP AS TIMESTAMP) AS Order_Time, b.QUANTITY, b.GROSS_SALES_BEFORE_TAX, b.DISCOUNT_BEFORE_TAX AS DISCOUNT, b.TAX, b.SHIPPING_PRICE, b.TOTAL_SALES AS SELLING_PRICE, UPPER(COALESCE(c.order_status, d.order_status)) AS OMS_order_status, UPPER(COALESCE(b.shipping_status, c.shipping_status, d.shipping_status)) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) AS FINAL_SHIPPING_STATUS, CAST(b.LINE_ITEM_ID AS VARCHAR(256)) AS SALEORDERITEMCODE, d.sales_order_item_id AS SALES_ORDER_ITEM_ID, COALESCE(b.awb, c.awb, d.awb) AS AWB, b.GATEWAY AS PAYMENT_GATEWAY, b.payment_mode, UPPER(COALESCE(c.Courier, d.courier, b.courier)) AS COURIER, COALESCE( CAST(b.Shipping_created_at AS TIMESTAMP), CAST(c.manifest_date AS TIMESTAMP), CAST(d.dispatch_date AS TIMESTAMP) ) AS DISPATCH_DATE, COALESCE( CAST(c.delivered_date AS TIMESTAMP), CAST(d.delivered_date AS TIMESTAMP), CASE WHEN LOWER(b.shipping_status) = \'delivered\' THEN CAST(b.shipping_status_update_date AS TIMESTAMP) END ) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, COALESCE( CASE WHEN b.IS_REFUND = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN 1 END, c.IS_REFUND, d.return_flag ) AS RETURN_FLAG, CASE WHEN COALESCE( CASE WHEN b.IS_REFUND = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN 1 END, c.IS_REFUND, d.return_flag ) = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN COALESCE(b.refund_quantity, 0) END AS returned_quantity, CASE WHEN COALESCE( CASE WHEN b.IS_REFUND = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN 1 END, c.IS_REFUND, d.return_flag ) = 1 AND LOWER(b.order_status) NOT IN (\'cancelled\') THEN COALESCE(b.refund_value, 0) END AS returned_sales, CASE WHEN LOWER(b.order_status) IN (\'cancelled\') THEN CAST(b.quantity AS BIGINT) END AS cancelled_quantity, b.shopify_new_customer_flag AS NEW_CUSTOMER_FLAG, UPPER(b.shopify_acquisition_product) AS acquisition_product, CAST(CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATEDIFF(day, CAST(COALESCE(b.shipping_status_update_date, c.shipping_last_update_date, d.shipping_last_update_date) AS DATE), CAST(b.ORDER_TIMESTAMP AS DATE)) WHEN LOWER(COALESCE(shipmap.final_shipping_status, b.shipping_status, c.shipping_status, d.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATEDIFF(day, CAST(b.ORDER_TIMESTAMP AS DATE), CURRENT_DATE) END AS BIGINT) AS Days_in_Shipment, b.shopify_acquisition_date AS MARKETPLACE_ACQUISITION_DATE, b.SKU_CODE, UPPER(COALESCE(b.PRODUCT_NAME_FINAL, c.productname)) AS PRODUCT_NAME_FINAL, UPPER(COALESCE(b.PRODUCT_CATEGORY, c.category)) AS PRODUCT_CATEGORY, UPPER(b.PRODUCT_SUB_CATEGORY) AS PRODUCT_SUB_CATEGORY, COALESCE(CASE WHEN b.commonsku = \'\' THEN NULL ELSE b.commonsku END, c.master_sku) AS commonsku, UPPER(COALESCE(c.warehouse_name, d.warehouse_name)) AS WAREHOUSE, COALESCE(b.pincode, d.pincode, c.pincode) AS pincode, COALESCE(c.pickup_pincode, fa.pincode) AS source_pincode, UPPER(b.source_name) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, COALESCE(b.order_type) AS Order_Type, c.invoice_date, b.refund_date_final, b.refund_value, b.cancelled_at, b.size FROM public.tuco_kids_shopify_fact_items b LEFT JOIN ( SELECT * FROM ( SELECT transactionid, final_source, channel, ROW_NUMBER() OVER (PARTITION BY transactionid ORDER BY 1) AS rn FROM public.tuco_kids_ga_order_by_source_consolidated ) x WHERE rn = 1 ) GA4 ON REPLACE(CAST(b.order_name AS VARCHAR), \'#\', \'\') = REPLACE(CAST(GA4.transactionid AS VARCHAR), \'#\', \'\') LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, Marketplace_LineItem_ID ORDER BY last_update_date DESC) AS rw FROM public.tuco_kids_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE \'%shopify%\' ) c ON REPLACE(CAST(b.order_name AS VARCHAR), \'#\', \'\') = REPLACE(CAST(c.reference_code AS VARCHAR), \'#\', \'\') AND REPLACE(CAST(b.LINE_ITEM_ID AS VARCHAR), \'`\', \'\') = REPLACE(CAST(c.Marketplace_LineItem_ID AS VARCHAR), \'`\', \'\') LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, SPLIT_PART(saleorderitemcode, \'-\', 1) ORDER BY shipping_last_update_date DESC) AS rw FROM public.tuco_kids_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%shopify%\' ) d WHERE rw = 1 ) d ON b.order_id = d.order_id AND b.line_item_id = SPLIT_PART(d.saleorderitemcode, \'-\', 1) LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY LOWER(facility) ORDER BY 1) AS rw FROM public.facility_pincode ) fa WHERE rw = 1 ) fa ON LOWER(d.warehouse_name) = LOWER(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM public.shipment_status_mapping ) shipmap WHERE rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, c.shipping_status, d.shipping_status, b.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) UNION ALL SELECT NULL::VARCHAR(256) AS customer_id, UPPER(SHOP_NAME) AS SHOP_NAME, UPPER(marketplace) AS marketplace, UPPER(marketplace) AS CHANNEL, UPPER(marketplace) AS SOURCE, ORDER_ID, reference_code, NULL::VARCHAR(256) AS tags, contact_num AS PHONE, customer_name AS NAME, email AS EMAIL, CAST(shipping_last_update_date AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, SKU, PRODUCT_ID, UPPER(PRODUCTNAME) AS PRODUCT_NAME, CURRENCY, UPPER(CITY) AS City, UPPER(STATE) AS State, UPPER(ORDER_STATUS) AS Order_Status, CAST(CAST(ORDER_DATE AS TIMESTAMP) AS DATE) AS Order_Date, CAST(ORDER_DATE AS TIMESTAMP) AS ORDER_TIMESTAMP, SUBORDER_QUANTITY AS QUANTITY, COALESCE(SELLING_PRICE, 0) - COALESCE(tax, 0) + COALESCE(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, SHIPPING_PRICE, SELLING_PRICE, UPPER(ORDER_STATUS) AS OMS_Order_Status, UPPER(b.Shipping_status) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS, Marketplace_LineItem_ID AS SALEORDERITEMCODE, suborder_id AS SALES_ORDER_ITEM_ID, AWB, NULL::VARCHAR(256) AS Payment_Gateway, payment_mode AS Payment_Mode, UPPER(COURIER) AS COURIER, CAST(MANIFEST_DATE AS TIMESTAMP) AS DISPATCH_DATE, CAST(DELIVERED_DATE AS TIMESTAMP) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, IS_REFUND AS RETURN_FLAG, CASE WHEN is_refund = 1 THEN CAST(suborder_quantity AS BIGINT) END AS returned_quantity, CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN COALESCE(is_refund, 0) END AS returned_sales, CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS BIGINT) END AS cancelled_quantity, CAST(new_customer_flag AS VARCHAR(256)) AS NEW_CUSTOMER_FLAG, NULL::VARCHAR(256) AS ACQUISITION_PRODUCT, CAST(Days_in_shipment AS BIGINT) AS DAYS_IN_SHIPMENT, NULL::DATE AS ACQUISITION_DATE, SKU AS SKU_CODE, UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL, UPPER(mapped_category) AS PRODUCT_CATEGORY, null::varchar(256) AS PRODUCT_SUB_CATEGORY, COALESCE(CASE WHEN b.commonsku = \'\' THEN NULL ELSE b.commonsku END, b.master_SKU) AS commonsku, UPPER(WAREHOUSE_NAME) AS WAREHOUSE, pincode, pickup_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, NULL::VARCHAR(256) AS Order_Type, b.invoice_date, NULL::DATE AS refund_date_final, NULL::NUMERIC AS refund_value, NULL::TIMESTAMP AS cancelled_at, b.size FROM public.tuco_kids_EasyEcom_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM public.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE NOT ( LOWER(marketplace) LIKE \'%shopify%\' OR LOWER(marketplace) LIKE \'%amazon%\' OR LOWER(marketplace) LIKE \'%flipkart%\' OR LOWER(marketplace) LIKE \'%blinkit%\' OR LOWER(marketplace) LIKE \'%swiggy%\' OR LOWER(marketplace) LIKE \'%zepto%\' OR LOWER(marketplace) LIKE \'%b2b%\' ) UNION ALL SELECT NULL::VARCHAR(256) AS customer_id, UPPER(afi.SHOP_NAME) AS Shop_name, CASE WHEN afi.shop_name like \'Amazon_FBA\' THEN \'AMAZON FBA\' ELSE \'AMAZON\' END AS marketplace, \'AMAZON\' AS CHANNEL, \'AMAZON\' AS SOURCE, afi.ORDER_ID, afi.ORDER_ID AS reference_code, NULL::VARCHAR(256) AS tags, NULL::VARCHAR(256) AS PHONE, afi.NAME, COALESCE(EEFI.EMAIL, UFI.EMAIL, AFI.EMAIL) AS EMAIL, COALESCE( CAST(EEFI.shipping_last_update_date AS TIMESTAMP), CAST(UFI.shipping_last_update_date AS TIMESTAMP) ) AS SHIPPING_LAST_UPDATE_DATE, afi.SKU, CAST(afi.PRODUCT_ID AS VARCHAR(256)) AS PRODUCT_ID, afi.PRODUCT_NAME, afi.CURRENCY, UPPER(afi.CITY) AS CITY, UPPER(afi.STATE) AS State, UPPER(afi.ORDER_STATUS) AS Order_Status, CAST(afi.ORDER_TIMESTAMP AS DATE) AS Order_Date, CAST(afi.ORDER_TIMESTAMP AS TIMESTAMP) AS Order_Time, afi.QUANTITY, COALESCE(TOTAL_SALES, 0) - COALESCE(afi.tax, 0) + COALESCE(DISCOUNT_BEFORE_TAX, 0) AS GROSS_SALES_BEFORE_TAX, DISCOUNT_BEFORE_TAX AS DISCOUNT, afi.TAX, afi.SHIPPING_PRICE, TOTAL_SALES AS SELLING_PRICE, UPPER(COALESCE(EEFI.order_status, UFI.order_status)) AS OMS_order_status, UPPER(COALESCE(EEFI.shipping_status, UFI.shipping_status)) AS SHIPPING_STATUS, UPPER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) AS FINAL_SHIPPING_STATUS, afi.ORDER_ID::VARCHAR || \'-\' || afi.PRODUCT_ID::VARCHAR AS SALEORDERITEMCODE, afi.ORDER_ID::VARCHAR || \'-\' || afi.PRODUCT_ID::VARCHAR AS SALES_ORDER_ITEM_ID, COALESCE(EEFI.awb, UFI.awb) AS AWB, NULL::VARCHAR(256) AS Payment_Gateway, UPPER(COALESCE(EEFI.payment_mode, UFI.payment_mode)) AS Payment_Mode, UPPER(COALESCE(EEFI.Courier, UFI.courier)) AS COURIER, CAST(COALESCE(EEFI.manifest_date, UFI.dispatch_date) AS TIMESTAMP) AS DISPATCH_DATE, CAST(COALESCE(EEFI.delivered_date, UFI.delivered_date) AS TIMESTAMP) AS DELIVERED_DATE, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, UFI.shipping_status, EEFI.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS, afi.IS_REFUND AS RETURN_FLAG, CASE WHEN afi.is_refund = 1 THEN CAST(afi.quantity AS BIGINT) END AS returned_quantity, CASE WHEN afi.is_refund = 1 THEN afi.total_sales END AS returned_sales, CASE WHEN afi.is_refund = 0 AND LOWER(afi.order_status) = \'cancelled\' THEN CAST(afi.quantity AS BIGINT) END AS cancelled_quantity, NULL::VARCHAR(256) AS NEW_CUSTOMER_FLAG, NULL::VARCHAR(256) AS ACQUISITION_PRODUCT, CASE WHEN LOWER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) IN (\'delivered\', \'delivered to origin\') THEN DATEDIFF(day, CAST(afi.ORDER_TIMESTAMP AS DATE), CURRENT_DATE) WHEN LOWER(COALESCE(shipmap.final_shipping_status, EEFI.shipping_status, UFI.shipping_status)) IN (\'in transit\', \'shipment created\') THEN DATEDIFF(day, CAST(afi.ORDER_TIMESTAMP AS DATE), CURRENT_DATE) END AS Days_in_Shipment, NULL::DATE AS ACQUISITION_DATE, COALESCE(afi.SKU, UFI.PRODUCT_ID, EEFI.SKU) AS SKU_CODE, UPPER(AFI.PRODUCT_NAME_FINAL) AS PRODUCT_NAME_FINAL, UPPER(AFI.PRODUCT_CATEGORY) AS PRODUCT_CATEGORY, UPPER(AFI.PRODUCT_SUB_CATEGORY) AS PRODUCT_SUB_CATEGORY, COALESCE(CASE WHEN AFI.commonsku = \'\' THEN NULL ELSE AFI.commonsku END, CAST(AFI.commonsku AS VARCHAR(256))) AS commonsku, REPLACE(REPLACE(REPLACE(REPLACE(UPPER(EEFI.warehouse_NAME),\'AMAZON_FBA_\',\'\'),\'_AUTO\',\'\'),\'UNBOTTLE PRIVATE LIMITED - \',\'\'),\'_SELLERFLEX\',\'\') AS WAREHOUSE, CAST(eefi.pincode AS VARCHAR(20)) AS pincode, CAST(pickup_pincode AS VARCHAR(20)) AS pickup_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, afi.Order_Type, COALESCE(eefi.invoice_date) AS Invoice_Date, NULL::DATE AS refund_date_final, NULL::NUMERIC AS refund_value, NULL::TIMESTAMP AS cancelled_at, afi.size FROM public.tuco_kids_amazon_fact_items AFI LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY reference_code, SKU ORDER BY last_update_date DESC) AS rw FROM public.tuco_kids_EasyEcom_FACT_ITEMS ) z WHERE z.rw = 1 AND LOWER(marketplace) LIKE \'%amazon%\' ) EEFI ON AFI.Order_id = EEFI.reference_code AND AFI.SKU = EEFI.sku LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, product_id ORDER BY shipping_last_update_date DESC) AS rw FROM public.tuco_kids_UNICOMMERCE_FACT_ITEMS WHERE LOWER(marketplace) LIKE \'%amazon%\' ) ufi WHERE ufi.rw = 1 ) UFI ON CAST(AFI.order_id AS VARCHAR(256)) = CAST(UFI.order_id AS VARCHAR(256)) AND CAST(AFI.product_id AS VARCHAR(256)) = CAST(UFI.PRODUCT_ID AS VARCHAR(256)) LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY LOWER(facility) ORDER BY 1) AS rw FROM public.facility_pincode ) fa WHERE rw = 1 ) fa ON LOWER(ufi.warehouse_name) = LOWER(fa.facility) LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM public.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(EEFI.shipping_status, UFI.shipping_status, afi.ORDER_STATUS)) = LOWER(ShipMap.shipping_status) UNION ALL SELECT ffi.customer_id AS customer_id, UPPER(ffi.shop_name) AS SHOP_NAME, UPPER(ffi.shop_name) as marketplace, \'FLIPKART\' AS CHANNEL, \'FLIPKART\' AS SOURCE, ffi.\"order id\" AS ORDER_ID, ffi.order_name AS reference_code, ffi.tags AS tags, ffi.phone AS PHONE, ffi.name AS NAME, ffi.email AS EMAIL, COALESCE( CAST(ffi.order_service_completion_date AS TIMESTAMP), CAST(ffi.delivery_date AS TIMESTAMP), CAST(ffi.dispatch_date AS TIMESTAMP) ) AS SHIPPING_LAST_UPDATE_DATE, ffi.SKU AS SKU, ffi.product_id AS PRODUCT_ID, UPPER(ffi.PRODUCT_NAME) AS PRODUCT_NAME, \'INR\' AS CURRENCY, UPPER(ffi.city) AS CITY, UPPER(ffi.state) AS State, UPPER(CASE WHEN ffi.cancellation_date IS NOT NULL THEN \'CANCELLED\' WHEN ffi.return_id IS NOT NULL THEN \'RETURNED\' WHEN ffi.delivery_date IS NOT NULL THEN \'DELIVERED\' WHEN ffi.dispatch_date IS NOT NULL THEN \'SHIPPED\' ELSE ffi.order_item_status END) AS ORDER_STATUS, CAST(ffi.order_date AS DATE) AS Order_Date, CAST(ffi.order_date AS TIMESTAMP) AS Order_Time, ffi.quantity AS QUANTITY, ffi.gross_sales_before_tax AS GROSS_SALES_BEFORE_TAX, ffi.discount_before_tax AS DISCOUNT, ffi.tax AS TAX, ffi.shipping_price AS SHIPPING_PRICE, ffi.total_sales AS SELLING_PRICE, UPPER(ffi.order_item_status) AS OMS_order_status, UPPER(CASE WHEN ffi.delivery_date IS NOT NULL THEN \'DELIVERED\' WHEN ffi.dispatch_date IS NOT NULL THEN \'IN TRANSIT\' WHEN ffi.cancellation_date IS NOT NULL THEN \'CANCELLED\' WHEN ffi.return_id IS NOT NULL THEN \'RETURNED\' ELSE ffi.order_item_status END) AS SHIPPING_STATUS, UPPER(CASE WHEN ffi.delivery_date IS NOT NULL THEN \'DELIVERED\' WHEN ffi.dispatch_date IS NOT NULL THEN \'IN TRANSIT\' WHEN ffi.cancellation_date IS NOT NULL THEN \'CANCELLED\' WHEN ffi.return_id IS NOT NULL THEN \'RETURNED\' ELSE ffi.order_item_status END) AS FINAL_SHIPPING_STATUS, ffi.line_item_id AS SALEORDERITEMCODE, ffi.line_item_id AS SALES_ORDER_ITEM_ID, AWB, NULL::VARCHAR(256) AS PAYMENT_GATEWAY, UPPER(ffi.payment_mode) AS payment_mode, courier AS COURIER, CAST(ffi.dispatch_date AS TIMESTAMP) AS DISPATCH_DATE, CAST(ffi.delivery_date AS TIMESTAMP) AS DELIVERED_DATE, CASE WHEN ffi.delivery_date IS NOT NULL THEN 1 ELSE 0 END AS DELIVERED_STATUS, ffi.is_refund AS RETURN_FLAG, CASE WHEN ffi.is_refund = 1 THEN CAST(ffi.quantity AS BIGINT) END AS returned_quantity, CASE WHEN ffi.is_refund = 1 THEN ffi.total_sales END AS returned_sales, CASE WHEN ffi.cancellation_date IS NOT NULL THEN CAST(ffi.quantity AS BIGINT) END AS cancelled_quantity, NULL::VARCHAR(256) AS NEW_CUSTOMER_FLAG, NULL::VARCHAR(256) AS acquisition_product, CAST(CASE WHEN ffi.delivery_date IS NOT NULL THEN DATEDIFF(day, CAST(ffi.order_date AS DATE), CAST(ffi.delivery_date AS DATE)) WHEN ffi.dispatch_date IS NOT NULL THEN DATEDIFF(day, CAST(ffi.order_date AS DATE), CURRENT_DATE) END AS BIGINT) AS Days_in_Shipment, NULL::DATE AS MARKETPLACE_ACQUISITION_DATE, ffi.SKU AS SKU_CODE, UPPER(COALESCE(sm.Product_name, ffi.PRODUCT_NAME)) AS PRODUCT_NAME_FINAL, UPPER(COALESCE(sm.category, ffi.category)) AS PRODUCT_CATEGORY, UPPER(sm.sub_category) AS PRODUCT_SUB_CATEGORY, coalesce(ffi.commonsku,sm.commonsku) AS commonsku, UPPER(ffi.\"Warehouse ID\") AS WAREHOUSE, ffi.pincode AS pincode, NULL::VARCHAR(20) AS source_pincode, NULL::VARCHAR(256) AS Source_name, NULL::VARCHAR(256) AS Mapped_Source_Name, \'B2C\' AS Order_Type, NULL::DATE AS invoice_date, CAST(ffi.return_approval_date AS DATE) AS refund_date_final, CASE WHEN ffi.is_refund = 1 THEN ffi.total_sales END AS refund_value, ffi.cancellation_date AS cancelled_at, ffi.size FROM public.tuco_kids_flipkart_fact_items ffi LEFT JOIN ( SELECT * FROM ( SELECT commonsku as sku, commonsku, category, sub_category, Product_name, ROW_NUMBER() OVER (PARTITION BY SKU ORDER BY 1) AS rw FROM public.tuco_kids_SKU_Master ) WHERE rw = 1 ) sm ON ffi.SKU = sm.SKU UNION ALL SELECT null::varchar AS customer_id, \'BLINKIT\' AS SHOP_NAME, \'BLINKIT\' marketplace, \'BLINKIT\' AS CHANNEL, \'BLINKIT\' AS SOURCE, bi.order_id AS ORDER_ID, bi.order_id AS reference_code, null::varchar AS tags, null::varchar AS PHONE, null::varchar AS NAME, null::varchar AS EMAIL, bi.order_date AS SHIPPING_LAST_UPDATE_DATE, bi.commonSKU AS SKU, bi.product_id AS PRODUCT_ID, UPPER(bi.PRODUCT_NAME) AS PRODUCT_NAME, \'INR\' AS CURRENCY, UPPER(bi.city) AS CITY, null::varchar AS State, \'DELIVERED\' AS ORDER_STATUS, CAST(bi.order_date AS DATE) AS Order_Date, CAST(bi.order_date AS TIMESTAMP) AS Order_Time, bi.quantity AS QUANTITY, bi.Selling_Price_final AS GROSS_SALES_BEFORE_TAX, null::DOUBLE PRECISION AS DISCOUNT, null::DOUBLE PRECISION AS TAX, null::DOUBLE PRECISION AS SHIPPING_PRICE, bi.Selling_Price_final AS SELLING_PRICE, \'DELIVERED\' AS OMS_order_status, \'DELIVERED\' AS SHIPPING_STATUS, \'DELIVERED\' AS FINAL_SHIPPING_STATUS, bi.order_id AS SALEORDERITEMCODE, bi.order_id AS SALES_ORDER_ITEM_ID, null::varchar AWB, NULL::VARCHAR(256) AS PAYMENT_GATEWAY, null::varchar AS payment_mode, \'BLINKIT\' AS COURIER, CAST(bi.order_date AS TIMESTAMP) AS DISPATCH_DATE, CAST(bi.order_date AS TIMESTAMP) AS DELIVERED_DATE, 1 AS DELIVERED_STATUS, 0 AS RETURN_FLAG, 0 AS returned_quantity, 0 AS returned_sales, 0 AS cancelled_quantity, NULL::VARCHAR(256) A